def substract_elements(test_tup1, test_tup2):
    """
    Subtract the contents of one tuple from the corresponding index of another tuple.

    Works on flat tuples of numbers as well as tuples of nested tuples.
    """
    def _sub(a, b):
        if isinstance(a, tuple) and isinstance(b, tuple):
            return tuple(_sub(x, y) for x, y in zip(a, b))
        return a - b

    return tuple(_sub(x, y) for x, y in zip(test_tup1, test_tup2))

