def get_lcm(l):
    """
    Find the LCM of the given array elements.

    Args:
        l: An iterable of integers.

    Returns:
        The least common multiple of all elements. Returns 0 if any
        element is 0. Raises ValueError on an empty iterable.
    """
    nums = list(l)
    if not nums:
        raise ValueError("cannot compute lcm of an empty sequence")

    def _lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

    return reduce(_lcm, nums)

