    Find the LCM (least common multiple) of the given array elements.

    Args:
        l: An iterable of integers.

    Returns:
        The LCM of all elements. Returns 0 if any element is 0,
        and 1 for an empty iterable.
    """
    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

    return reduce(lcm, l, 1)

