def rencontres_number(n, m):
    """
    Compute the rencontres number D(n, m): the number of permutations of n
    elements having exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements, given by the recurrence
    D(k, 0) = (k - 1) * (D(k - 1, 0) + D(k - 2, 0)).
    """
    from math import comb

    if n < 0 or m < 0 or m > n:
        return 0

    # Number of derangements of k elements, computed iteratively.
    def derangements(k):
        prev, curr = 1, 0  # D(0, 0) = 1, D(1, 0) = 0
        if k == 0:
            return prev
        for i in range(2, k + 1):
            prev, curr = curr, (i - 1) * (curr + prev)
        return curr

    return comb(n, m) * derangements(n - m)

def rencontres_number(n, m):
    from math import comb

    def derangements(k):
        # D(k, 0): permutations of k elements with no fixed points
        a, b = 1, 0  # D(0,0)=1, D(1,0)=0
        if k == 0:
            return a
        if k == 1:
            return b
        for i in range(2, k + 1):
            a, b = b, (i - 1) * (a + b)
        return b

    if n < 0 or m < 0 or m > n:
        return 0
    if m == 0:
        return derangements(n)
    return comb(n, m) * derangements(n - m)

def rencontres_number(n, m):
    """
    Compute the rencontres number D(n, m): the number of permutations of n
    elements that have exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements.
    """
    from math import comb

    if n < 0 or m < 0 or m > n:
        return 0

    if m > 0:
        return comb(n, m) * rencontres_number(n - m, 0)

    # m == 0: count derangements of n elements iteratively
    # D(0, 0) = 1, D(1, 0) = 0, D(k, 0) = (k - 1) * (D(k-1, 0) + D(k-2, 0))
    prev, curr = 1, 0  # D(0, 0), D(1, 0)
    if n == 0:
        return prev
    for k in range(2, n + 1):
        prev, curr = curr, (k - 1) * (curr + prev)
    return curr

def rencontres_number(n, m):
    """
    Compute the rencontres number D(n, m): the number of permutations of
    n elements having exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements.
    """
    if n < 0 or m < 0 or m > n:
        return 0

    # Derangement count D(k, 0) via the recurrence D(k) = (k-1)*(D(k-1) + D(k-2))
    def derangements(k):
        prev, cur = 1, 0  # D(0) = 1, D(1) = 0
        if k == 0:
            return prev
        for i in range(2, k + 1):
            prev, cur = cur, (i - 1) * (cur + prev)
        return cur

    # Binomial coefficient C(n, m) without relying on math.comb
    def binomial(a, b):
        b = min(b, a - b)
        result = 1
        for i in range(b):
            result = result * (a - i) // (i + 1)
        return result

    return binomial(n, m) * derangements(n - m)

def rencontres_number(n, m):
    """
    Return the rencontres number D(n, m): the count of permutations of n
    elements that have exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements.
    """
    from math import comb

    if n < 0 or m < 0 or m > n:
        return 0
    if n == 0 and m == 0:
        return 1
    if n == 1 and m == 0:
        return 0
    if m == 0:
        # Derangements: D(k, 0) = (k - 1) * (D(k-1, 0) + D(k-2, 0))
        prev, curr = 1, 0  # D(0, 0), D(1, 0)
        for k in range(2, n + 1):
            prev, curr = curr, (k - 1) * (curr + prev)
        return curr
    return comb(n, m) * rencontres_number(n - m, 0)

