def sqrt_perfect_number(n):
    """
    Return the square root of a perfect (square) number.

    The result is returned as an int when n is a perfect square,
    otherwise the floating-point square root is returned.
    """
    if n < 0:
        raise ValueError("cannot take the square root of a negative number")
    root = math.isqrt(int(n)) if float(n).is_integer() else None
    if root is not None and root * root == int(n):
        return root
    return math.sqrt(n)

