        if x <= 0:
            return 0
        total = 0
        i = 0
        while (1 << i) <= x:
            block = 1 << (i + 1)
            full = (x + 1) // block
            total += full * (1 << i)
            rem = (x + 1) % block
            total += max(0, rem - (1 << i))
            i += 1
        return total

    return count_upto(n)

