def largest_adjacent_product(nums):
    """
    Find the largest product of a pair of adjacent elements in a list of integers.

    Args:
        nums: A list of integers with at least two elements.

    Returns:
        The maximum product formed by multiplying two neighboring elements.

    Raises:
        ValueError: If the list contains fewer than two elements.
    """
    if len(nums) < 2:
        raise ValueError("Need at least two elements to form an adjacent pair.")
    return max(nums[i] * nums[i + 1] for i in range(len(nums) - 1))


