def count_Set_Bits(n):
    total = 0
    i = 0
    while (1 << i) <= n:
        block = 1 << (i + 1)
        total += ((n + 1) // block) * (1 << i)
        rem = (n + 1) % block
        total += max(0, rem - (1 << i))
        i += 1
    return total


