def substract_elements(test_tup1, test_tup2):
    """
    Subtract the contents of one tuple with the corresponding index of the other tuple.

    Works for flat tuples of numbers as well as tuples of nested tuples.

    >>> substract_elements(((1, 3), (4, 5), (2, 9), (1, 10)), ((6, 7), (3, 9), (1, 1), (7, 3)))
    ((-5, -4), (1, -4), (1, 8), (-6, 7))
    >>> substract_elements((10, 20, 30), (1, 2, 3))
    (9, 18, 27)
    """
    def _sub(a, b):
        if isinstance(a, tuple) and isinstance(b, tuple):
            return tuple(_sub(x, y) for x, y in zip(a, b))
        return a - b

    return tuple(_sub(a, b) for a, b in zip(test_tup1, test_tup2))

