def rencontres_number(n, m):
    """
    Compute the rencontres number D(n, m): the number of permutations of n
    elements with exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements.
    """
    if n < 0 or m < 0 or m > n:
        return 0

    def binomial(a, b):
        if b < 0 or b > a:
            return 0
        result = 1
        for i in range(min(b, a - b)):
            result = result * (a - i) // (i + 1)
        return result

    def derangements(k):
        # D(0) = 1, D(1) = 0, D(k) = (k - 1) * (D(k - 1) + D(k - 2))
        prev, curr = 1, 0
        if k == 0:
            return 1
        for i in range(2, k + 1):
            prev, curr = curr, (i - 1) * (curr + prev)
        return curr

    return binomial(n, m) * derangements(n - m)


