def toggle_middle_bits(n):
    """
    Toggle all bits of n except the first (most significant) and last bit.

    Examples:
        toggle_middle_bits(9)  -> 15   # 1001 -> 1111
        toggle_middle_bits(10) -> 12   # 1010 -> 1100
        toggle_middle_bits(11) -> 13   # 1011 -> 1101
    """
    if n <= 2:
