def count_Set_Bits(n):
    """Count the total number of set bits in the binary representations
    of all integers from 1 to n (inclusive)."""
    if n <= 0:
        return 0

    total = 0
    i = 0
    while (1 << i) <= n:
        bit = 1 << i          # value of the current bit position
        block = bit << 1      # full cycle length: bit zeros then bit ones
        count = n + 1         # numbers considered: 0..n

        # complete cycles each contribute `bit` ones at this position
        total += (count // block) * bit
        # partial cycle contributes whatever falls in the "ones" half
        total += max(0, (count % block) - bit)

        i += 1

    return total


