def area_tetrahedron(side):
    """
    Calculate the total surface area of a regular tetrahedron.

    A regular tetrahedron has 4 congruent equilateral triangular faces.
    Each face has area (sqrt(3) / 4) * side**2, so the total is
    4 * (sqrt(3) / 4) * side**2 = sqrt(3) * side**2.

    Args:
        side: Length of an edge of the tetrahedron (non-negative number).

    Returns:
        float: The total surface area.

    Raises:
        ValueError: If side is negative.
