def count_Substrings(s, n=None):
    from collections import defaultdict

    s = str(s)
    if n is None:
        n = len(s)
    else:
        n = min(n, len(s))

    seen = defaultdict(int)
    seen[0] = 1
    prefix = 0
    count = 0

