def count_Set_Bits(n):
    """
    Count the total number of set bits (1s) in the binary representation
    of all integers from 1 to n inclusive.
    """
    if n <= 0:
        return 0

    total = 0
    power = 1  # represents 2**i, the bit position being counted

    while power <= n:
        # Number of complete cycles of length 2*power in [0, n]
        full_cycles = (n + 1) // (2 * power)
        total += full_cycles * power

        # Remaining partial cycle contributes set bits too
        remainder = (n + 1) % (2 * power)
        total += max(0, remainder - power)

        power <<= 1

    return total


