    total = 0
    i = 0
    while (1 << i) <= n:
        block = 1 << (i + 1)
        half = 1 << i
        total += (n + 1) // block * half
        rem = (n + 1) % block
        if rem > half:
            total += rem - half
        i += 1
    return total


