    """
    Compute the rencontres number D(n, m): the number of permutations of
    n elements that have exactly m fixed points.

    D(n, m) = C(n, m) * D(n - m, 0), where D(k, 0) is the number of
    derangements of k elements.
    """
    if n < 0 or m < 0 or m > n:
        return 0

    # Base cases for derangements
    if n == 0 and m == 0:
        return 1
    if n == 1 and m == 0:
        return 0

    if m == 0:
        # Recurrence: D(n, 0) = (n - 1) * (D(n - 1, 0) + D(n - 2, 0))
        prev, curr = 1, 0  # D(0, 0), D(1, 0)
        for k in range(2, n + 1):
            prev, curr = curr, (k - 1) * (curr + prev)
        return curr

    # Binomial coefficient C(n, m) computed iteratively to stay exact
    binom = 1
    for i in range(m):
        binom = binom * (n - i) // (i + 1)

    return binom * rencontres_number(n - m, 0)

