import math

def sqrt_root(num):
    """
    Return the square root of the given (perfect square) number.

    Uses integer square root when the input is an exact perfect square so the
    result stays precise, otherwise falls back to a floating point square root.
    """
    if num < 0:
        raise ValueError("cannot take the square root of a negative number")

    if isinstance(num, int):
        root = math.isqrt(num)
        if root * root == num:
            return root

    return math.sqrt(num)


