def rencontres_number(n, m):
    """
    Return the rencontres number D(n, m): the number of permutations of
    n elements having exactly m fixed points.
    """
    def binomial(n, k):
        if k < 0 or k > n:
            return 0
        result = 1
        for i in range(min(k, n - k)):
            result = result * (n - i) // (i + 1)
        return result

    def derangements(n):
        # D(n, 0): permutations of n elements with no fixed points
        if n < 0:
            return 0
        prev, curr = 1, 0  # D(0)=1, D(1)=0
        if n == 0:
            return prev
        for i in range(2, n + 1):
            prev, curr = curr, (i - 1) * (curr + prev)
        return curr

    if n < 0 or m < 0 or m > n:
        return 0
    return binomial(n, m) * derangements(n - m)


