    Count the total number of set bits (1s) in the binary representation
    of all integers from 1 to n inclusive.

    Runs in O(log n) time using the observation that, for each bit
    position, the bit pattern cycles as `powerOf2` zeros followed by
    `powerOf2` ones.
    """
    if n <= 0:
        return 0

    n += 1                  # work with the half-open range [0, n+1)
    power_of_2 = 2
    count = n // 2          # contribution of the least significant bit

    while power_of_2 <= n:
        total_pairs = n // power_of_2
        # each complete pair of blocks contributes `power_of_2` set bits
        count += (total_pairs // 2) * power_of_2
        # handle a trailing, partially filled block of ones
        if total_pairs & 1:
            count += n % power_of_2
        power_of_2 <<= 1

    return count


