def count_Set_Bits(n):
    """
    Count the total number of set bits in the binary representations
    of all integers from 1 to n (inclusive).
    """
    if n <= 0:
        return 0

    total = 0
    power = 1  # represents 2**i, the bit position weight

    while power <= n:
        # Number of complete cycles of length 2*power within [0, n]
        cycle_len = power << 1
        full_cycles = (n + 1) // cycle_len
        total += full_cycles * power

        # Handle the leftover partial cycle
        remainder = (n + 1) % cycle_len
        if remainder > power:
            total += remainder - power

        power = cycle_len

    return total


