import math

def sqrt_root(num):
    """
    Return the square root of the given number.

    Uses math.isqrt for exact integer results when the input is a
    perfect square, otherwise falls back to a float square root.
    """
    if num < 0:
        raise ValueError("cannot take the square root of a negative number")
    if isinstance(num, int):
        root = math.isqrt(num)
        if root * root == num:
            return root
    return math.sqrt(num)

