def count_Set_Bits(n):
    """
    Count the total number of set bits in the binary representations
    of all integers from 1 to n (inclusive).
    """
    if n < 1:
        return 0

    n += 1  # work with the half-open range [0, n+1) for easier math
    count = n // 2
    power_of_2 = 2

    while power_of_2 <= n:
        total_pairs = n // power_of_2
        # each complete pair of blocks contributes power_of_2 set bits
        count += (total_pairs // 2) * power_of_2
        # handle the trailing incomplete block
        if total_pairs & 1:
            count += n % power_of_2
        power_of_2 <<= 1

    return count


