import re

def is_decimal(num):
    """
    Check whether the given string is a decimal number with a precision of
    at most 2 digits after the decimal point.

    Examples:
        is_decimal('123.11')    -> True
        is_decimal('e666.86')   -> False
        is_decimal('3.124587')  -> False
        is_decimal('1.1.11')    -> False
    """
