def rencontres_number(n, m):
    """
    Return the rencontres number D(n, m): the number of permutations of n
    elements having exactly m fixed points.
    """
    def binomial_coeff(n, k):
        if k < 0 or k > n:
            return 0
        k = min(k, n - k)
        result = 1
        for i in range(k):
            result = result * (n - i) // (i + 1)
        return result

    if n < 0 or m < 0 or m > n:
        return 0

    # Base cases for the derangement recurrence D(n, 0).
    if n == 0 and m == 0:
        return 1
    if n == 1 and m == 0:
        return 0

    if m == 0:
        # D(n, 0) = (n - 1) * (D(n - 1, 0) + D(n - 2, 0))
        return (n - 1) * (rencontres_number(n - 1, 0) + rencontres_number(n - 2, 0))

    # D(n, m) = C(n, m) * D(n - m, 0)
    return binomial_coeff(n, m) * rencontres_number(n - m, 0)


